import { memo, useRef } from 'react'

import { tabList } from './TabList.css'

/*

const entries = useMemo(() => [
    {
        id: 'panel1',
        label: 'panel1',
        panel: <Panel1 />,
    },
    {
        id: 'panel2',
        label: 'panel2',
        panel: <Panel2 />,
    },
], [])

<Tabs entries={entries} />
*/

export default memo(function Tabs({ entries }) {
  const tabsRef = useRef(new Map())
  const panelsRef = useRef(new Map())

  return (
    <div className={tabList}>
      <div
        role="tablist"
        onKeyDown={(e) => {
          // focused tab will be e.target
          const id = e.target.id

          // just make sure we're not dealing with shit, unmounting and the like
          const tab = tabsRef.current.get(id)
          if (tab == null) return

          let newId
          switch (e.key) {
            case 'Home':
              newId = tab.parentNode.firstChild.id
              break
            case 'End':
              newId = tab.parentNode.lastChild.id
              break
            case 'ArrowLeft':
              newId = tab.previousSibling?.id ?? tab.parentNode.lastChild.id
              break
            case 'ArrowRight':
              newId = tab.nextSibling?.id ?? tab.parentNode.firstChild.id
              break
            default:
              return
          }

          e.preventDefault()
          e.stopPropagation()
          tabsRef.current.get(newId).focus()
        }}
      >
        {entries.map((entry, index) => (
          <button
            key={entry.id}
            id={`tab-${entry.id}`}
            ref={(node) => {
              if (node) tabsRef.current.set(`tab-${entry.id}`, node)
              else tabsRef.current.delete(`tab-${entry.id}`)
            }}
            type="button"
            role="tab"
            aria-controls={`panel-${entry.id}`}
            aria-selected={index === 0}
            tabIndex={index === 0 ? 0 : -1}
            onClick={(e) => {
              const id = e.target.id
              const panelId = e.target.getAttribute('aria-controls')

              // mark all buttons as non-selected except the clicked one
              tabsRef.current.values().forEach((tab) => {
                tab.setAttribute('aria-selected', tab.id === id)
                tab.tabIndex = tab.id === id ? 0 : -1
              })

              // mark all panels as hidden except the clicked one
              panelsRef.current.values().forEach((panel) => {
                panel.hidden = panel.id !== panelId
              })
            }}
          >
            {entry.label}
          </button>
        ))}
      </div>
      {entries.map((entry, index) => (
        <div
          key={entry.id}
          id={`panel-${entry.id}`}
          ref={(node) => {
            if (node) panelsRef.current.set(`panel-${entry.id}`, node)
            else panelsRef.current.delete(`panel-${entry.id}`)
          }}
          role="tabpanel"
          aria-labelledby={`tab-${entry.id}`}
          tabIndex={0}
          hidden={index !== 0}
        >
          {entry.panel}
        </div>
      ))}
    </div>
  )
})
